CREATE OR REPLACE FUNCTION public.log_audit_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    current_user_id UUID;
    record_tenant_id UUID;
BEGIN
    BEGIN
        current_user_id := auth.uid();
    EXCEPTION WHEN OTHERS THEN
        current_user_id := NULL;
    END;

    BEGIN
        IF TG_TABLE_NAME = 'tenants' THEN
            IF TG_OP = 'DELETE' THEN
                record_tenant_id := OLD.id;
            ELSE
                record_tenant_id := NEW.id;
            END IF;
        ELSE
            IF TG_OP = 'DELETE' THEN
                record_tenant_id := OLD.tenant_id;
            ELSE
                record_tenant_id := NEW.tenant_id;
            END IF;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        record_tenant_id := NULL;
    END;

    BEGIN
        INSERT INTO public.audit_logs (
            tenant_id,
            table_name,
            record_id,
            action,
            old_data,
            new_data,
            changed_by_id
        ) VALUES (
            record_tenant_id,
            TG_TABLE_NAME,
            COALESCE(NEW.id, OLD.id),
            TG_OP,
            CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN row_to_json(OLD)::jsonb ELSE NULL END,
            CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN row_to_json(NEW)::jsonb ELSE NULL END,
            current_user_id
        );
    EXCEPTION WHEN OTHERS THEN
        RAISE WARNING 'audit_log_event failed for table % op %: %', TG_TABLE_NAME, TG_OP, SQLERRM;
    END;

    IF TG_OP = 'DELETE' THEN
        RETURN OLD;
    ELSE
        RETURN NEW;
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$

